        {%- set is_tool = True -%}
        {%- set role = "user" -%}
    {%- else -%}
        {%- set role = message['role'] -%}
    {%- endif -%}
    {{ '<start_of_turn>' + role + '\n' + (first_user_prefix if loop.first else "") }}
    {%- if is_tool -%}
        {{ '```tool_outputs\n' }}
    {%- endif -%}
    {%- if 'content' in message -%}
        {%- for item in message['content'] -%}
            {%- if item['type'] == 'audio' -%}
                {{ '<audio_soft_token>' }}
            {%- elif item['type'] == 'image' -%}
                {{ '<image_soft_token>' }}
            {%- elif item['type'] == 'text' -%}
                {{ item['text'] | trim }}
            {%- endif -%}
            {%- if is_tool -%}
                {{ '\n' }}
            {%- endif -%}
        {%- endfor -%}
    {%- endif -%}
    {%- if is_tool -%}
        {{ '```' }}
