                    {{- key + '=' + tool_call['arguments'][key] -}}
                    {% if not loop.last %}
                        {{- ', ' -}}
                    {% endif %}
                {%- endfor %}
            {{- ')\n' -}}
            {%- endif -%}
        {%- endfor -%}
        {{- '```' -}}
    {%- endif -%}
    {{ '<end_of_turn>\n' }}
{%- endfor -%}
{%- if add_generation_prompt -%}
    {{'<start_of_turn>model\n'}}
{%- endif -%}

{%- if not is_appending_to_prefill -%}
    {{ bos_token }}
    {%- if tools %}
