                    {%- if item['type'] == 'audio' -%}
                        {{ '<audio_soft_token>' }}
                    {%- elif item['type'] == 'image' -%}
                        {{ '<image_soft_token>' }}
                    {%- elif item['type'] == 'text' -%}
                        {{ item['text'] | trim }}
                    {%- endif -%}
                    {%- if is_tool -%}
                        {{ '\n' }}
                    {%- endif -%}
                {%- endfor -%}
            {%- else -%}
                {{ raise_exception("Invalid content type") }}
            {%- endif -%}
        {%- endif -%}
        {%- if is_tool -%}
            {{ '```' }}
            {%- set is_tool = False -%}
        {%- endif -%}
        {%- if 'tool_calls' in message -%}
            {{- '```tool_code\n' -}}
            {%- for tool_call in message['tool_calls'] -%}
                {%- if 'function' in tool_call -%}
