                        {% endif %}
                    {%- endfor %}
                {{- ')\n' -}}
                {%- endif -%}
            {%- endfor -%}
            {{- '```' -}}
        {%- endif -%}
        {{'<ctrl100>\n'}}
    {%- endfor -%}
{%- else -%}
    {%- if (message['role'] == 'assistant') -%}
