        {%- set is_tool = True -%}
        {%- set role = "user" -%}
    {%- elif (message['role'] == 'system') -%}
        {%- set is_system = True -%}
        {%- set role = "user" -%}
    {%- else -%}
        {%- set role = message['role'] -%}
    {%- endif -%}
    {%- if is_first_part -%}
        {{ '<ctrl99>' + role + '\n' }}
        {%- if is_tool -%}
            {{ '```tool_outputs\n' }}
        {%- endif -%}
    {%- endif -%}
    {%- if 'content' in message -%}
        {%- if message['content'] is string -%}
            {{ message['content'] }}
