                    {{ item['text'] }}
                {%- endif -%}
                {%- if is_tool -%}
                    {{ '\n' }}
                {%- endif -%}
                {%- if is_system and loop.last -%}
                    {{- '\n\n' -}}
                {%- endif -%}
            {%- endfor -%}
        {%- else -%}
            {{ raise_exception("Invalid content type") }}
